local function _bx(a,b) local r,p=0,1; a=a%256;b=b%256; for _=1,8 do if (a%2)~=(b%2) then r=r+p end; a=math.floor(a/2);b=math.floor(b/2);p=p*2 end; return r end
local function _ks(len,idx)
  local s=0xA5A5F00D
  for i=1,#_M do s=(s*1664525+_M[i]+1013904223)%4294967296 end
  s=(s*1664525+(idx*2654435761)+1013904223)%4294967296
  local out=table.create(len)
  for i=1,len do s=(s*1664525+1013904223)%4294967296; out[i]=math.floor(s/65536)%256 end
  return out
end
